//! Typed columns, conditions and the query builder.

use crate::db::{Backend, Conn, Executor, Row};
use crate::error::{Error, Result};
use crate::model::{primary_key, Model};
use crate::relation::{Join, Related, Relation, WithQuery};
use crate::sql::{column_list, Cond, Fragment, Sort, SortTerm, Sql};
use crate::value::{SqlType, Value};
use serde::Serialize;
use std::marker::PhantomData;

/// A typed column of model `M` holding `T`, generated by the derive as
/// `User::EMAIL`. Builds conditions, orderings and assignments.
///
/// For a nullable field (`Option<T>`) the column type is `T`; use
/// [`is_null`](Column::is_null) and [`set_null`](Column::set_null) for
/// `NULL`.
pub struct Column<M, T> {
    name: &'static str,
    _marker: PhantomData<fn() -> (M, T)>,
}

impl<M, T> Clone for Column<M, T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M, T> Copy for Column<M, T> {}

impl<M, T> std::fmt::Debug for Column<M, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Column({})", self.name)
    }
}

impl<M, T> Column<M, T> {
    #[doc(hidden)]
    pub const fn new(name: &'static str) -> Self {
        Self { name, _marker: PhantomData }
    }

    /// The column name.
    pub const fn name(&self) -> &'static str {
        self.name
    }

    /// `IS NULL`
    pub fn is_null(&self) -> Expr<M> {
        Expr::new(Cond::Null(self.name, false))
    }

    /// `IS NOT NULL`
    pub fn is_not_null(&self) -> Expr<M> {
        Expr::new(Cond::Null(self.name, true))
    }

    /// Ascending order.
    pub fn asc(&self) -> Order<M> {
        Order::new(SortTerm::Column(self.name), false)
    }

    /// Descending order.
    pub fn desc(&self) -> Order<M> {
        Order::new(SortTerm::Column(self.name), true)
    }
}

impl<M, T: SqlType> Column<M, T> {
    fn compare(&self, op: &'static str, value: impl Into<T>) -> Expr<M> {
        Expr::new(Cond::Compare(self.name, op, value.into().to_value()))
    }

    /// `= value`
    pub fn eq(&self, value: impl Into<T>) -> Expr<M> {
        self.compare("=", value)
    }

    /// `<> value`
    pub fn ne(&self, value: impl Into<T>) -> Expr<M> {
        self.compare("<>", value)
    }

    /// `> value`
    pub fn gt(&self, value: impl Into<T>) -> Expr<M> {
        self.compare(">", value)
    }

    /// `>= value`
    pub fn gte(&self, value: impl Into<T>) -> Expr<M> {
        self.compare(">=", value)
    }

    /// `< value`
    pub fn lt(&self, value: impl Into<T>) -> Expr<M> {
        self.compare("<", value)
    }

    /// `<= value`
    pub fn lte(&self, value: impl Into<T>) -> Expr<M> {
        self.compare("<=", value)
    }

    /// `IN (values...)`; false when `values` is empty.
    pub fn is_in<V: Into<T>>(&self, values: impl IntoIterator<Item = V>) -> Expr<M> {
        let values = values.into_iter().map(|v| v.into().to_value()).collect();
        Expr::new(Cond::In(self.name, values, false))
    }

    /// `NOT IN (values...)`; true when `values` is empty.
    pub fn not_in<V: Into<T>>(&self, values: impl IntoIterator<Item = V>) -> Expr<M> {
        let values = values.into_iter().map(|v| v.into().to_value()).collect();
        Expr::new(Cond::In(self.name, values, true))
    }

    /// Sets the column, for [`Query::update`].
    pub fn set(&self, value: impl Into<T>) -> Assignment<M> {
        Assignment { column: self.name, value: value.into().to_value(), _marker: PhantomData }
    }

    /// Sets the column to `NULL`, for [`Query::update`].
    pub fn set_null(&self) -> Assignment<M> {
        Assignment { column: self.name, value: Value::Null(T::KIND), _marker: PhantomData }
    }
}

impl<M> Column<M, String> {
    /// `LIKE pattern`, with `%` and `_` wildcards. Case-sensitive in
    /// PostgreSQL, case-insensitive for ASCII in SQLite.
    pub fn like(&self, pattern: impl Into<String>) -> Expr<M> {
        Expr::new(Cond::Compare(self.name, "LIKE", Value::Text(pattern.into())))
    }
}

/// A condition on model `M`. Combine with [`and`](Expr::and),
/// [`or`](Expr::or), [`not`](Expr::not) or the `&`, `|` and `!` operators.
pub struct Expr<M> {
    pub(crate) cond: Cond,
    _marker: PhantomData<fn() -> M>,
}

impl<M> Clone for Expr<M> {
    fn clone(&self) -> Self {
        Expr::new(self.cond.clone())
    }
}

impl<M> std::fmt::Debug for Expr<M> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.cond.fmt(f)
    }
}

impl<M> Expr<M> {
    pub(crate) fn new(cond: Cond) -> Self {
        Self { cond, _marker: PhantomData }
    }

    /// A condition written in SQL, for what the typed columns can't
    /// express: JSONB and full-text operators, functions, casts. Each `?`
    /// is bound to the next value of `args` (a tuple, array or `Vec`; `()`
    /// for none), and `??` writes a literal `?`, such as PostgreSQL's JSONB
    /// `?` operator. The fragment is parenthesized, so it combines safely
    /// with other conditions.
    ///
    /// Column names are not quoted or qualified. In a
    /// [join](Query::join), the main table is `t0` and the joined one `t1`.
    ///
    /// ```no_run
    /// # use axeon_orm::{Db, Expr, Model};
    /// # #[derive(Model)] struct Product { id: i64, name: String, fields: serde_json::Value, price: i64 }
    /// # async fn run(db: Db) -> axeon_orm::Result<()> {
    /// let certified = Product::query()
    ///     .filter(Expr::raw("fields @> ?::jsonb", (serde_json::json!({ "certs": ["CE"] }),)))
    ///     .filter(Expr::raw("fields ?? 'moq'", ()))
    ///     .filter(Product::PRICE.lt(100))
    ///     .all(&db)
    ///     .await?;
    /// # Ok(()) }
    /// ```
    ///
    /// # Panics
    ///
    /// When the number of `?` placeholders differs from the number of
    /// values.
    ///
    /// # Safety of values
    ///
    /// Values are always sent as bound parameters. Never build `sql` from
    /// user input; pass it through `args` instead.
    pub fn raw(sql: &str, args: impl RawArgs) -> Expr<M> {
        Expr::new(Cond::Raw(Fragment::new(sql, args.into_values())))
    }

    /// Both conditions.
    pub fn and(self, other: Expr<M>) -> Expr<M> {
        Expr::new(Cond::And(vec![self.cond, other.cond]))
    }

    /// Either condition.
    pub fn or(self, other: Expr<M>) -> Expr<M> {
        Expr::new(Cond::Or(vec![self.cond, other.cond]))
    }

    /// The opposite condition.
    #[allow(clippy::should_implement_trait)]
    pub fn not(self) -> Expr<M> {
        Expr::new(Cond::Not(Box::new(self.cond)))
    }

    /// True when all the conditions hold (or there are none).
    pub fn all(exprs: impl IntoIterator<Item = Expr<M>>) -> Expr<M> {
        Expr::new(Cond::And(exprs.into_iter().map(|e| e.cond).collect()))
    }

    /// True when any of the conditions holds (false when there are none).
    pub fn any(exprs: impl IntoIterator<Item = Expr<M>>) -> Expr<M> {
        Expr::new(Cond::Or(exprs.into_iter().map(|e| e.cond).collect()))
    }
}

impl<M> std::ops::BitAnd for Expr<M> {
    type Output = Expr<M>;
    fn bitand(self, other: Expr<M>) -> Expr<M> {
        self.and(other)
    }
}

impl<M> std::ops::BitOr for Expr<M> {
    type Output = Expr<M>;
    fn bitor(self, other: Expr<M>) -> Expr<M> {
        self.or(other)
    }
}

impl<M> std::ops::Not for Expr<M> {
    type Output = Expr<M>;
    fn not(self) -> Expr<M> {
        Expr::not(self)
    }
}

/// An `ORDER BY` term, from [`Column::asc`], [`Column::desc`],
/// [`Order::raw`] or [`Order::raw_desc`].
pub struct Order<M> {
    sort: Sort,
    _marker: PhantomData<fn() -> M>,
}

impl<M> Clone for Order<M> {
    fn clone(&self) -> Self {
        Order { sort: self.sort.clone(), _marker: PhantomData }
    }
}

impl<M> std::fmt::Debug for Order<M> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.sort.fmt(f)
    }
}

impl<M> Order<M> {
    fn new(term: SortTerm, descending: bool) -> Self {
        Order { sort: Sort { term, descending, qualifier: None }, _marker: PhantomData }
    }

    /// Ascending order by an SQL expression, such as a vector distance or a
    /// full-text rank. Placeholders work as in [`Expr::raw`].
    ///
    /// ```no_run
    /// # use axeon_orm::{Db, Model, Order};
    /// # #[derive(Model)] struct Product { id: i64, category: String }
    /// # async fn run(db: Db) -> axeon_orm::Result<()> {
    /// // Nearest products in a category, with pgvector.
    /// let nearest = Product::query()
    ///     .filter(Product::CATEGORY.eq("lighting"))
    ///     .order_by(Order::raw("embedding <=> ?::vector", ("[0.12,0.5,0.33]",)))
    ///     .limit(20)
    ///     .all(&db)
    ///     .await?;
    /// # Ok(()) }
    /// ```
    ///
    /// # Panics
    ///
    /// When the number of `?` placeholders differs from the number of
    /// values.
    pub fn raw(sql: &str, args: impl RawArgs) -> Order<M> {
        Order::new(SortTerm::Raw(Fragment::new(sql, args.into_values())), false)
    }

    /// Descending order by an SQL expression; see [`Order::raw`].
    ///
    /// # Panics
    ///
    /// When the number of `?` placeholders differs from the number of
    /// values.
    pub fn raw_desc(sql: &str, args: impl RawArgs) -> Order<M> {
        Order::new(SortTerm::Raw(Fragment::new(sql, args.into_values())), true)
    }
}

/// The values bound to [`Expr::raw`] and [`Order::raw`]: `()` for none, a
/// tuple of up to eight values of different types, or an array or `Vec`
/// of one type. Each value converts [`Into<Value>`](Value).
pub trait RawArgs {
    /// The values, in placeholder order.
    fn into_values(self) -> Vec<Value>;
}

impl<T: Into<Value>> RawArgs for Vec<T> {
    fn into_values(self) -> Vec<Value> {
        self.into_iter().map(Into::into).collect()
    }
}

impl<T: Into<Value>, const N: usize> RawArgs for [T; N] {
    fn into_values(self) -> Vec<Value> {
        self.into_iter().map(Into::into).collect()
    }
}

macro_rules! raw_args_tuple {
    ($($name:ident),*) => {
        impl<$($name: Into<Value>),*> RawArgs for ($($name,)*) {
            #[allow(non_snake_case)]
            fn into_values(self) -> Vec<Value> {
                let ($($name,)*) = self;
                vec![$($name.into()),*]
            }
        }
    };
}

raw_args_tuple!();
raw_args_tuple!(A);
raw_args_tuple!(A, B);
raw_args_tuple!(A, B, C);
raw_args_tuple!(A, B, C, D);
raw_args_tuple!(A, B, C, D, E);
raw_args_tuple!(A, B, C, D, E, F);
raw_args_tuple!(A, B, C, D, E, F, G);
raw_args_tuple!(A, B, C, D, E, F, G, H);

/// A `SET column = value` term, from [`Column::set`].
pub struct Assignment<M> {
    column: &'static str,
    value: Value,
    _marker: PhantomData<fn() -> M>,
}

/// One page of results from [`Query::paginate`].
#[derive(Clone, Debug, Serialize)]
pub struct Page<T> {
    /// The rows on this page.
    pub items: Vec<T>,
    /// The page number, from 1.
    pub page: u64,
    /// Rows per page.
    pub per_page: u64,
    /// Rows across all pages.
    pub total: u64,
    /// The last page number (at least 1).
    pub last_page: u64,
}

/// A `SELECT` on model `M`, from `M::query()`. Builder methods take and
/// return the query; the `async` methods run it.
///
/// ```no_run
/// # use axeon_orm::{Db, Model};
/// # #[derive(Model)] struct User { id: i64, name: String, age: i32 }
/// # async fn run(db: Db) -> axeon_orm::Result<()> {
/// let adults = User::query()
///     .filter(User::AGE.gte(18))
///     .order_by(User::NAME.asc())
///     .limit(20)
///     .all(&db)
///     .await?;
/// # Ok(()) }
/// ```
pub struct Query<M> {
    conds: Vec<Cond>,
    order: Vec<Sort>,
    limit: Option<u64>,
    offset: Option<u64>,
    _marker: PhantomData<fn() -> M>,
}

impl<M> Clone for Query<M> {
    fn clone(&self) -> Self {
        Self {
            conds: self.conds.clone(),
            order: self.order.clone(),
            limit: self.limit,
            offset: self.offset,
            _marker: PhantomData,
        }
    }
}

impl<M> std::fmt::Debug for Query<M> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Query")
            .field("conds", &self.conds)
            .field("order", &self.order)
            .field("limit", &self.limit)
            .field("offset", &self.offset)
            .finish()
    }
}

impl<M: Model> Default for Query<M> {
    fn default() -> Self {
        Self::new()
    }
}

impl<M: Model> Query<M> {
    /// Every row of the table.
    pub fn new() -> Self {
        Self { conds: Vec::new(), order: Vec::new(), limit: None, offset: None, _marker: PhantomData }
    }

    /// Keeps rows matching `expr`. Several filters must all match.
    pub fn filter(mut self, expr: Expr<M>) -> Self {
        self.conds.push(expr.cond);
        self
    }

    pub(crate) fn cond(mut self, cond: Cond) -> Self {
        self.conds.push(cond);
        self
    }

    /// Sorts by a column (or an [`Order::raw`] expression); call again for
    /// tie-breakers.
    pub fn order_by(mut self, order: Order<M>) -> Self {
        self.order.push(order.sort);
        self
    }

    /// Returns at most `n` rows.
    pub fn limit(mut self, n: u64) -> Self {
        self.limit = Some(n);
        self
    }

    /// Skips the first `n` rows.
    pub fn offset(mut self, n: u64) -> Self {
        self.offset = Some(n);
        self
    }

    /// Also loads a relation for every row, in one extra query:
    /// `User::query().with(User::POSTS).all(&db)` gives `(User, Vec<Post>)`
    /// pairs.
    pub fn with<R: Relation<M>>(self, relation: R) -> WithQuery<M, R> {
        WithQuery::new(self, relation)
    }

    /// Keeps rows with at least one related record:
    /// `User::query().has(User::POSTS)`.
    pub fn has<R: Related<M>>(self, relation: R) -> Self {
        self.cond(relation.related_cond(None, false).0)
    }

    /// Keeps rows without any related record.
    pub fn doesnt_have<R: Related<M>>(self, relation: R) -> Self {
        self.cond(relation.related_cond(None, true).0)
    }

    /// Keeps rows with at least one related record matching `expr`:
    /// `User::query().where_has(User::POSTS, Post::PUBLISHED.eq(true))`.
    pub fn where_has<R: Related<M>>(self, relation: R, expr: Expr<R::Target>) -> Self {
        self.cond(relation.related_cond(Some(expr), false).0)
    }

    /// Keeps rows without any related record matching `expr`.
    pub fn where_doesnt_have<R: Related<M>>(self, relation: R, expr: Expr<R::Target>) -> Self {
        self.cond(relation.related_cond(Some(expr), true).0)
    }

    /// Joins a `belongs_to`, `has_one` or `has_many` relation in the same
    /// query, keeping rows that have a match: gives `(M, Related)` pairs.
    /// With `has_many`, a row appears once per related record.
    pub fn join<R: Join<M>>(self, relation: R) -> JoinQuery<M, R::Target, R::Target> {
        JoinQuery::new(self, relation.on())
    }

    /// Like [`join`](Query::join), but keeps rows without a match:
    /// gives `(M, Option<Related>)` pairs.
    pub fn left_join<R: Join<M>>(self, relation: R) -> JoinQuery<M, R::Target, Option<R::Target>> {
        JoinQuery::new(self, relation.on())
    }

    fn select(&self, backend: Backend) -> (String, Vec<Value>) {
        let mut sql = Sql::new(backend);
        sql.push("SELECT ").push(&column_list::<M>(backend)).push(" FROM ").ident(M::TABLE);
        sql.where_clause(&self.conds);
        sql.order_by(&self.order);
        sql.limit_offset(self.limit, self.offset);
        sql.finish()
    }

    pub(crate) async fn fetch(&self, conn: &mut Conn<'_>) -> Result<Vec<M>> {
        let (sql, args) = self.select(conn.backend());
        conn.fetch_all(sql, args).await?.iter().map(M::from_row).collect()
    }

    /// Every matching row.
    pub async fn all<'c>(self, ex: impl Executor<'c>) -> Result<Vec<M>> {
        self.fetch(&mut ex.into_conn()).await
    }

    /// The first matching row.
    pub async fn first<'c>(self, ex: impl Executor<'c>) -> Result<Option<M>> {
        Ok(self.limit(1).all(ex).await?.into_iter().next())
    }

    /// The first matching row, or [`Error::NotFound`].
    pub async fn first_or_fail<'c>(self, ex: impl Executor<'c>) -> Result<M> {
        self.first(ex).await?.ok_or(Error::NotFound)
    }

    /// Runs `SELECT <expr> AS value` over the matching rows.
    async fn scalar<T: SqlType>(&self, conn: &mut Conn<'_>, expr: &str) -> Result<T> {
        let mut sql = Sql::new(conn.backend());
        sql.push("SELECT ").push(expr).push(" AS ").ident("value").push(" FROM ").ident(M::TABLE);
        sql.where_clause(&self.conds);
        let (sql, args) = sql.finish();
        let row = conn.fetch_optional(sql, args).await?.ok_or(Error::NotFound)?;
        row.get::<T>("value")
    }

    async fn count_on(&self, conn: &mut Conn<'_>) -> Result<u64> {
        Ok(self.scalar::<i64>(conn, "COUNT(*)").await?.max(0) as u64)
    }

    /// How many rows match; ignores order, limit and offset.
    pub async fn count<'c>(self, ex: impl Executor<'c>) -> Result<u64> {
        self.count_on(&mut ex.into_conn()).await
    }

    /// Whether any row matches.
    pub async fn exists<'c>(self, ex: impl Executor<'c>) -> Result<bool> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("SELECT 1 AS ").ident("one").push(" FROM ").ident(M::TABLE);
        sql.where_clause(&self.conds);
        sql.push(" LIMIT 1");
        let (sql, args) = sql.finish();
        Ok(conn.fetch_optional(sql, args).await?.is_some())
    }

    /// `aggregate(column)`, cast to a fixed type so every database returns
    /// the same Rust type.
    fn aggregate(backend: Backend, function: &str, column: &str, float: bool) -> String {
        let target = match (backend, float) {
            (Backend::Postgres, true) => "DOUBLE PRECISION",
            (Backend::Postgres, false) => "BIGINT",
            (Backend::MySql, true) => "DOUBLE",
            (Backend::MySql, false) => "SIGNED",
            (_, true) => "REAL",
            (_, false) => "INTEGER",
        };
        format!("CAST({}({}) AS {})", function, crate::sql::ident(backend, column), target)
    }

    /// The sum of a numeric column over the matching rows (`None` when no
    /// rows match). Integer columns sum to `i64`, float columns to `f64`.
    pub async fn sum<'c, T: Numeric>(self, ex: impl Executor<'c>, column: Column<M, T>) -> Result<Option<T::Sum>> {
        let mut conn = ex.into_conn();
        let expr = Self::aggregate(conn.backend(), "SUM", column.name, T::FLOAT);
        self.scalar::<Option<T::Sum>>(&mut conn, &expr).await
    }

    /// The average of a numeric column, or `None` when no rows match.
    pub async fn avg<'c, T: Numeric>(self, ex: impl Executor<'c>, column: Column<M, T>) -> Result<Option<f64>> {
        let mut conn = ex.into_conn();
        let expr = Self::aggregate(conn.backend(), "AVG", column.name, true);
        self.scalar::<Option<f64>>(&mut conn, &expr).await
    }

    /// The smallest value of a column, or `None` when no rows match.
    pub async fn min<'c, T: SqlType>(self, ex: impl Executor<'c>, column: Column<M, T>) -> Result<Option<T>> {
        let mut conn = ex.into_conn();
        let expr = format!("MIN({})", crate::sql::ident(conn.backend(), column.name));
        self.scalar::<Option<T>>(&mut conn, &expr).await
    }

    /// The largest value of a column, or `None` when no rows match.
    pub async fn max<'c, T: SqlType>(self, ex: impl Executor<'c>, column: Column<M, T>) -> Result<Option<T>> {
        let mut conn = ex.into_conn();
        let expr = format!("MAX({})", crate::sql::ident(conn.backend(), column.name));
        self.scalar::<Option<T>>(&mut conn, &expr).await
    }

    /// How many matching rows have each value of a column, ordered by the
    /// value. Rows where the column is `NULL` are left out.
    ///
    /// ```no_run
    /// # use axeon_orm::{Db, Model};
    /// # #[derive(Model)] struct Order { id: i64, status: String }
    /// # async fn run(db: Db) -> axeon_orm::Result<()> {
    /// for (status, n) in Order::query().count_by(&db, Order::STATUS).await? {
    ///     println!("{}: {}", status, n);
    /// }
    /// # Ok(()) }
    /// ```
    pub async fn count_by<'c, T: SqlType>(self, ex: impl Executor<'c>, column: Column<M, T>) -> Result<Vec<(T, u64)>> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("SELECT ").ident(column.name).push(" AS ").ident("key");
        sql.push(", COUNT(*) AS ").ident("count").push(" FROM ").ident(M::TABLE);
        sql.where_clause(&self.conds);
        sql.where_clause(&[Cond::Null(column.name, true)]);
        sql.push(" GROUP BY ").ident(column.name).push(" ORDER BY ").ident(column.name);
        let (sql, args) = sql.finish();
        conn.fetch_all(sql, args)
            .await?
            .iter()
            .map(|row| Ok((row.get::<T>("key")?, row.get::<i64>("count")?.max(0) as u64)))
            .collect()
    }

    /// Page `page` (from 1) of `per_page` rows, with the total count.
    pub async fn paginate<'c>(self, ex: impl Executor<'c>, page: u64, per_page: u64) -> Result<Page<M>> {
        let mut conn = ex.into_conn();
        let (page, per_page) = (page.max(1), per_page.max(1));
        let total = self.count_on(&mut conn).await?;
        let items = self.limit(per_page).offset((page - 1).saturating_mul(per_page)).fetch(&mut conn).await?;
        Ok(Page { items, page, per_page, total, last_page: total.div_ceil(per_page).max(1) })
    }

    /// Deletes every matching row; returns how many. Without a filter this
    /// empties the table.
    pub async fn delete<'c>(self, ex: impl Executor<'c>) -> Result<u64> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("DELETE FROM ").ident(M::TABLE);
        sql.where_clause(&self.conds);
        let (sql, args) = sql.finish();
        conn.execute(sql, args).await
    }

    /// Updates every matching row; returns how many matched (MySQL counts
    /// only rows whose values changed).
    ///
    /// ```no_run
    /// # use axeon_orm::{Db, Model};
    /// # #[derive(Model)] struct User { id: i64, active: bool, age: i32 }
    /// # async fn run(db: Db) -> axeon_orm::Result<()> {
    /// User::query().filter(User::AGE.lt(13)).update(&db, [User::ACTIVE.set(false)]).await?;
    /// # Ok(()) }
    /// ```
    pub async fn update<'c>(self, ex: impl Executor<'c>, set: impl IntoIterator<Item = Assignment<M>>) -> Result<u64> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("UPDATE ").ident(M::TABLE).push(" SET ");
        let mut empty = true;
        for assignment in set {
            if !empty {
                sql.push(", ");
            }
            empty = false;
            sql.ident(assignment.column).push(" = ").arg(assignment.value);
        }
        if empty {
            return Ok(0);
        }
        sql.where_clause(&self.conds);
        let (sql, args) = sql.finish();
        conn.execute(sql, args).await
    }
}

/// A numeric column type for [`Query::sum`] and [`Query::avg`].
pub trait Numeric: SqlType {
    /// What the sum is read as: `i64` for integers, `f64` for floats.
    type Sum: SqlType;
    #[doc(hidden)]
    const FLOAT: bool;
}

impl Numeric for i32 {
    type Sum = i64;
    const FLOAT: bool = false;
}

impl Numeric for i64 {
    type Sum = i64;
    const FLOAT: bool = false;
}

impl Numeric for f64 {
    type Sum = f64;
    const FLOAT: bool = true;
}

/// How a joined row is read: `T` for an inner join, `Option<T>` for a left
/// join.
#[doc(hidden)]
pub trait JoinOutput<T: Model>: Sized + Send {
    const LEFT: bool;
    fn decode(row: &Row, prefix: &str) -> Result<Self>;
}

impl<T: Model> JoinOutput<T> for T {
    const LEFT: bool = false;
    fn decode(row: &Row, prefix: &str) -> Result<Self> {
        T::from_row_prefixed(row, prefix)
    }
}

impl<T: Model> JoinOutput<T> for Option<T> {
    const LEFT: bool = true;
    fn decode(row: &Row, prefix: &str) -> Result<Self> {
        let key = format!("{}{}", prefix, primary_key::<T>().name);
        if row.is_null(&key)? {
            Ok(None)
        } else {
            T::from_row_prefixed(row, prefix).map(Some)
        }
    }
}

const LEFT_ALIAS: &str = "t0";
const RIGHT_ALIAS: &str = "t1";

/// A query joining a related table, from [`Query::join`] or
/// [`Query::left_join`]. Filter and sort by either side.
///
/// ```no_run
/// # use axeon_orm::{Db, Model};
/// # #[derive(Model, Clone)] struct User { id: i64, name: String }
/// # #[derive(Model)] struct Post { id: i64, #[model(belongs_to = User)] user_id: i64, title: String }
/// # async fn run(db: Db) -> axeon_orm::Result<()> {
/// let rows: Vec<(Post, User)> = Post::query()
///     .join(Post::USER)
///     .filter_related(User::NAME.eq("Ada"))
///     .order_by(Post::TITLE.asc())
///     .all(&db)
///     .await?;
/// # Ok(()) }
/// ```
pub struct JoinQuery<M, T, O> {
    query: Query<M>,
    related: Vec<Cond>,
    order: Vec<Sort>,
    on: (&'static str, &'static str),
    _marker: PhantomData<fn() -> (T, O)>,
}

impl<M: Model, T: Model, O: JoinOutput<T>> JoinQuery<M, T, O> {
    fn new(query: Query<M>, on: (&'static str, &'static str)) -> Self {
        let order = query.order.iter().cloned().map(|sort| Sort { qualifier: Some(LEFT_ALIAS), ..sort }).collect();
        Self { query, related: Vec::new(), order, on, _marker: PhantomData }
    }

    /// Keeps rows matching a condition on the main model.
    pub fn filter(mut self, expr: Expr<M>) -> Self {
        self.query.conds.push(expr.cond);
        self
    }

    /// Keeps rows matching a condition on the joined model.
    pub fn filter_related(mut self, expr: Expr<T>) -> Self {
        self.related.push(expr.cond);
        self
    }

    /// Sorts by a column of the main model.
    pub fn order_by(mut self, order: Order<M>) -> Self {
        self.order.push(Sort { qualifier: Some(LEFT_ALIAS), ..order.sort });
        self
    }

    /// Sorts by a column of the joined model.
    pub fn order_by_related(mut self, order: Order<T>) -> Self {
        self.order.push(Sort { qualifier: Some(RIGHT_ALIAS), ..order.sort });
        self
    }

    /// Returns at most `n` rows.
    pub fn limit(mut self, n: u64) -> Self {
        self.query.limit = Some(n);
        self
    }

    /// Skips the first `n` rows.
    pub fn offset(mut self, n: u64) -> Self {
        self.query.offset = Some(n);
        self
    }

    fn write_from(&self, sql: &mut Sql) {
        sql.push(" FROM ").ident(M::TABLE).push(" AS ").ident(LEFT_ALIAS);
        sql.push(if O::LEFT { " LEFT JOIN " } else { " INNER JOIN " });
        sql.ident(T::TABLE).push(" AS ").ident(RIGHT_ALIAS).push(" ON ");
        sql.ident(LEFT_ALIAS).push(".").ident(self.on.0).push(" = ");
        sql.ident(RIGHT_ALIAS).push(".").ident(self.on.1);
        sql.where_clause_as(&self.query.conds, Some(LEFT_ALIAS));
        sql.where_clause_as(&self.related, Some(RIGHT_ALIAS));
    }

    /// Every matching pair.
    pub async fn all<'c>(self, ex: impl Executor<'c>) -> Result<Vec<(M, O)>> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("SELECT ");
        let columns = M::COLUMNS.iter().map(|c| (LEFT_ALIAS, c.name)).chain(T::COLUMNS.iter().map(|c| (RIGHT_ALIAS, c.name)));
        for (i, (alias, column)) in columns.enumerate() {
            if i > 0 {
                sql.push(", ");
            }
            sql.ident(alias).push(".").ident(column).push(" AS ").ident(&format!("{}_{}", alias, column));
        }
        self.write_from(&mut sql);
        sql.order_by(&self.order);
        sql.limit_offset(self.query.limit, self.query.offset);
        let (sql, args) = sql.finish();
        let left = format!("{}_", LEFT_ALIAS);
        let right = format!("{}_", RIGHT_ALIAS);
        conn.fetch_all(sql, args)
            .await?
            .iter()
            .map(|row| Ok((M::from_row_prefixed(row, &left)?, O::decode(row, &right)?)))
            .collect()
    }

    /// The first matching pair.
    pub async fn first<'c>(self, ex: impl Executor<'c>) -> Result<Option<(M, O)>> {
        Ok(self.limit(1).all(ex).await?.into_iter().next())
    }

    /// How many pairs match.
    pub async fn count<'c>(self, ex: impl Executor<'c>) -> Result<u64> {
        let mut conn = ex.into_conn();
        let mut sql = Sql::new(conn.backend());
        sql.push("SELECT COUNT(*) AS ").ident("count");
        self.write_from(&mut sql);
        let (sql, args) = sql.finish();
        let row = conn.fetch_optional(sql, args).await?.ok_or(Error::NotFound)?;
        Ok(row.get::<i64>("count")?.max(0) as u64)
    }
}
